FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
float hgsdfDodecahedronSoft(vec3 p, float r, float e)
{
    const vec3 v13 = normalize(vec3(0,    PHI,    1));
    const vec3 v14 = normalize(vec3(0,    -PHI,   1));
    const vec3 v15 = normalize(vec3(1,    0,      PHI));
    const vec3 v16 = normalize(vec3(-1,   0,      PHI));
    const vec3 v17 = normalize(vec3(PHI,  1,      0));
    const vec3 v18 = normalize(vec3(-PHI, 1,      0));

    float d = 0.0;
    d += pow(abs(dot(p, v13)), e);
    d += pow(abs(dot(p, v14)), e);
    d += pow(abs(dot(p, v15)), e);
    d += pow(abs(dot(p, v16)), e);
    d += pow(abs(dot(p, v17)), e);
    d += pow(abs(dot(p, v18)), e);

    return pow(d, 1./e) - r;
}
